import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"MySQL Custom Certificates","description":"","frontmatter":{},"headers":[],"relativePath":"pages/advanced/mysql_tls.md","filePath":"pages/advanced/mysql_tls.md"}`),a={name:`pages/advanced/mysql_tls.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="mysql-custom-certificates" tabindex="-1">MySQL Custom Certificates <a class="header-anchor" href="#mysql-custom-certificates" aria-label="Permalink to “MySQL Custom Certificates”">​</a></h1><p>SQL Exporter supports custom TLS certificates for MySQL connections. This is useful when you have a self-signed certificate, a certificate from a private CA, or want to use mTLS for MySQL connections.</p><p>To use custom TLS certificates for MySQL connections, you need to add the following parameters to the connection string:</p><ol><li><code>tls=custom</code> to indicate that you want to use a custom TLS configuration (required to enable custom TLS support);</li><li><code>tls-ca=&lt;PATH_TO_CA_CERT&gt;</code> to specify the path to the CA certificate file (if your certificate is self-signed or from a private CA);</li><li><code>tls-cert=&lt;PATH_TO_CLIENT_CERT&gt;</code> and <code>tls-key=&lt;PATH_TO_CLIENT_KEY&gt;</code> to specify the paths to the client certificate and key files if you want to use mTLS (if your MySQL server requires client authentication).</li></ol><p>The connection string would look like this:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql://user:password@hostname:port/dbname?tls=custom&amp;tls-ca=/path/to/ca.pem</span></span>
<span class="line"><span>mysql://user:password@hostname:port/dbname?tls=custom&amp;tls-cert=/path/to/client-cert.pem&amp;tls-key=/path/to/client-key.pem</span></span></code></pre></div><p>This configuration is only applied to MySQL as there is no way to provide the configuration natively. For other databases, you may want to consult their documentation on how to set up TLS connections and apply the necessary parameters to the connection string if it&#39;s supported by the driver.</p><p>TLS Configuration is bound to the <code>hostname+port</code> combinations, so if there are connections using the same <code>hostname+port</code> combination, they will share and re-use the same TLS configuration.</p>`,8)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};